SELECT COUNT(score)
FROM students;
-- 只計算 score 不為 NULL 的筆數

SELECT SUM(score)
FROM students;
-- 計算所有學生的 score 總和

SELECT SUM(price * quantity)
FROM orders;
-- 訂單金額加總（常見電商寫法）

